import { useState, useEffect } from 'react';

function Counter() {
  const [count, setCount] = useState(0);

  useEffect(() => {
    document.title = `عداد: ${count}`;
  }, [count]);

  return (
    <div>
      <p>العدد: {count}</p>
      <button onClick={() => setCount(c => c + 1)}>زيادة</button>
    </div>
  );
}

export default Counter;
